import {FIRST_STAGE,LAST_STAGE,RUNES,ENEMIES,ACTS,SCROLLS,GEAR,stageDesign,maxHP,initialState,newBattle,resolveTurn,advanceStage,possibleMoves,makeBoard,buyGear,buyScroll,trainRune} from './battle-engine.mjs?v=1';
import {BattleSound} from './battle-sound.mjs?v=2';

const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms));
const key=document.body.dataset.preview==='true'?'solar-relic-otherworld-preview':'solar-relic-otherworld-v1';
let state;try{state=JSON.parse(localStorage.getItem(key)||'null');}catch{state=null;}
if(!state&&document.body.dataset.preview==='true'){state=initialState();state.battle=newBattle(state);}
if(!state){location.replace('index.html');throw Error('이세계 입장 기록이 없습니다');}
if(!state.battle)state.battle=newBattle(state);
const audio=new BattleSound(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let selected=-1,busy=false,shopTab='gear',toastTimer,shuffleLeft=2;
const save=()=>{try{localStorage.setItem(key,JSON.stringify(state));}catch{}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400);}
function dialog(html,closable=true){$('#dialogBody').innerHTML=html;$('#dialogClose').hidden=!closable;if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){if($('#dialog').open)$('#dialog').close();}
const pct=(n,total)=>`${Math.max(0,Math.min(100,n/total*100))}%`;
function showFloating(s){const el=$('#floatingText');el.textContent=s;el.classList.remove('show');void el.offsetWidth;el.classList.add('show');}
function renderStats(){const d=stageDesign(state.stage),b=state.battle,m=ENEMIES[b.enemyId],n=m.sprite;
  $('#coinBadge').textContent=`◈ ${state.coins.toLocaleString()}`;$('#actLabel').textContent=`ACT ${['I','II','III','IV','V'][d.act]} · ${d.title}`;$('#stageTitle').textContent=`${state.stage} · ${d.name}`;$('#stageNumber').textContent=state.stage;$('#storyLine').textContent=d.story;
  $('#enemyKind').textContent=d.boss?'BOSS ENCOUNTER':d.guardian?'GUARDIAN':'MONSTER ENCOUNTER';$('#turnLabel').textContent=`${b.turn}턴`;$('#enemyName').textContent=d.name;$('#enemyHp').textContent=`${b.enemyHP} / ${d.hp}`;$('#enemyFill').style.width=pct(b.enemyHP,d.hp);$('#heroHp').textContent=`${b.heroHP} / ${maxHP(state)}`;$('#heroFill').style.width=pct(b.heroHP,maxHP(state));$('#shieldLabel').textContent=`보호막 ${b.shield}`;
  $('#enemyIntent').textContent=b.phase==='playing'?(b.delay?'반격 지연':`반격까지 ${d.cadence-b.enemyCharge}매치`):b.phase==='won'?'승리':'패배';
  $('#affinityHint').textContent=`약점: ${m.weak.map(i=>RUNES[i].name).join('·')}  ·  저항: ${m.resist.map(i=>RUNES[i].name).join('·')}`;
  $('#monsterSprite').style.backgroundPosition=`${(n%4)*100/3}% ${Math.floor(n/4)*50}%`;$('#monsterSprite').setAttribute('aria-label',m.name);
  $('#boardSizeLabel').textContent=`${d.size} × ${d.size} · ${d.colors}색`;$('#shuffleCount').textContent=shuffleLeft;
  $('#battleTip').textContent=`${m.name}의 약점: ${m.weak.map(i=>RUNES[i].name).join('·')}. ${d.cadence}번 매치마다 반격합니다. 이동 횟수 제한은 없습니다.`;
  $('#soundToggle').textContent=audio.enabled?'♫':'♩';
  const st=b.streak;$('#streakInfo').textContent=st.count?`${RUNES[st.color].name} ${st.count}연속 · ${st.count>=2?'마법 준비 완료':'같은 색 한 번 더!'}`:'같은 색을 두 번 연속 맞추세요';
  $('#combatBanner').textContent=b.phase==='playing'?st.count>=2?`${RUNES[st.color].spell} · 3연속부터 토템 Lv.2 이상 ×1.5`:'첫 매치는 충전 · 같은 색 두 번째부터 마법 발동':b.phase==='won'?'전투 승리! 보상을 받았습니다':'쓰러졌습니다. 장비를 갖추고 다시 도전하세요';
  $('#combatBanner').classList.toggle('boost',st.count>=2);$('#combatBanner').classList.toggle('danger',b.heroHP<maxHP(state)*.3);
}
function renderBoard(){const d=stageDesign(state.stage),board=$('#board');board.dataset.size=d.size;board.innerHTML=state.battle.board.map((g,i)=>{const rune=RUNES[g.color];return `<button class="gem ${selected===i?'selected':''} ${state.battle.streak.count&&state.battle.streak.color===g.color?'ready':''}" data-i="${i}" style="--gem:${rune.color};--deep:#17233e" aria-label="${i+1}번 ${rune.name} 보석"><span>${rune.icon}</span></button>`;}).join('');}
function renderRunes(){const b=state.battle;$('#runeList').innerHTML=RUNES.map((r,i)=>`<div class="rune ${state.levels[i]?'':'locked'} ${b.streak.color===i?'active':''}" style="--rune:${r.color}" title="${r.spell}"><i>${r.icon}</i><b>${r.name}</b><small>${state.levels[i]?'Lv.'+state.levels[i]:'잠김'}</small></div>`).join('');$('#scrollList').textContent=state.scrolls.length?`연계: ${state.scrolls.map(id=>SCROLLS.find(s=>s.id===id)?.name).join(' · ')}`:'연계 마법은 상점에서 스크롤을 구매하면 열립니다.';}
function render(){renderStats();renderBoard();renderRunes();save();}
function animateClass(el,name,time){el.classList.remove(name);void el.offsetWidth;el.classList.add(name);setTimeout(()=>el.classList.remove(name),time);}
let monsterPoseTimer,magePoseTimer;
const mageLabels={idle:'전투를 준비하는 마법사',cast:'마법을 시전하는 마법사',guard:'방어하는 마법사',hurt:'공격받는 마법사',groggy:'그로기 상태의 마법사',victory:'승리한 마법사'};
function setMagePose(pose,duration=0){clearTimeout(magePoseTimer);const el=$('#mageSprite');el.dataset.pose=pose;el.setAttribute('aria-label',mageLabels[pose]);if(duration)magePoseTimer=setTimeout(()=>{if(state.battle.phase==='playing')setMagePose('idle');},duration);}
function setMonsterPose(pose,duration=0){clearTimeout(monsterPoseTimer);const el=$('#monsterSprite');el.dataset.pose=pose;el.setAttribute('aria-label',`${ENEMIES[state.battle.enemyId].name}, ${pose==='idle'?'대기':pose==='attack'?'공격':pose==='guard'?'방어':pose==='groggy'?'그로기':'피격'}`);if(pose!=='idle')$('#enemyIntent').textContent={attack:'반격!',guard:'마법 저항 · 방어',groggy:'그로기 · 반격 지연',hurt:'피격'}[pose];else renderStats();if(duration)monsterPoseTimer=setTimeout(()=>{if(state.battle.phase==='playing')setMonsterPose('idle');},duration);}
function spellVisual(e,combo){const color=e.color,r=RUNES[color],orb=$('#spellProjectile'),ring=$('#impactRing'),arena=$('.arena');setMagePose('cast',reduced?100:900);orb.style.setProperty('--spell',r.color);ring.style.setProperty('--spell',r.color);ring.className=`impact-ring fx-${r.kind}${combo?' combo-'+combo.id:''}`;arena.classList.add(`cast-${r.kind}`);if(combo)arena.classList.add(`cast-${combo.id}`);orb.classList.toggle('combo',!!combo);animateClass(orb,'fly',520);setTimeout(()=>{animateClass(ring,'burst',640);setMonsterPose(e.affinity<1?'guard':'hurt',600);if(e.affinity<1)audio.guard();else animateClass($('#monsterSprite'),'hurt',450);if(navigator.vibrate&&!reduced)navigator.vibrate(color===2?[40,35,85]:[55,35,65]);},reduced?0:390);setTimeout(()=>{arena.classList.remove(`cast-${r.kind}`);if(combo)arena.classList.remove(`cast-${combo.id}`);},reduced?100:850);}
async function playEvents(events){let combo=null;for(const e of events){
  if(e.kind==='match'){audio.match();showFloating(`${RUNES[e.color].name} ${e.removed}개`);await sleep(reduced?30:210);}
  else if(e.kind==='charge'){audio.charge();toast(e.count===1?`${RUNES[e.color].name} 충전! 같은 색을 한 번 더 맞추세요`:`${RUNES[e.color].name} 연속 충전`);}
  else if(e.kind==='combo'){combo=e;audio.combo(e.id);toast(`${e.name} 연계 마법!`);}
  else if(e.kind==='spell'){audio.spell(e.color,e.multiplier);spellVisual(e,combo);showFloating(`${combo?combo.name:RUNES[e.color].spell} · ${e.damage}`);await sleep(reduced?60:600);if(e.affinity>1)toast('약점 적중 · 피해 ×1.45');if(e.affinity<1)toast('마법 저항 · 피해 감소');combo=null;}
  else if(e.kind==='burn'){toast(`화상 피해 ${e.damage}`);}
  else if(e.kind==='counter'){audio.counter();setMonsterPose('attack',reduced?70:600);setMagePose(e.damage?'hurt':'guard',reduced?70:700);if(e.blocked)audio.guard();animateClass($('#monsterSprite'),'counter',560);animateClass($('.hero-line'),'counter',560);showFloating(`${e.attack} · ${e.damage?'−'+e.damage:'방어!'}`);await sleep(reduced?40:550);}
  else if(e.kind==='delayed'){audio.stun();setMonsterPose('groggy',reduced?100:1200);toast('그로기! 몬스터 반격 지연');}
  else if(e.kind==='victory'){audio.victory();setMagePose('victory');setMonsterPose('groggy');$('#monsterSprite').classList.add('die');await sleep(reduced?50:800);showVictory(e);}
  else if(e.kind==='defeat'){audio.defeat();setMagePose('groggy');setMonsterPose('idle');await sleep(reduced?50:300);showDefeat();}
}}
async function swap(a,b){if(busy||$('#dialog').open||state.battle.phase!=='playing')return;audio.unlock();const result=resolveTurn(state,a,b);selected=-1;if(!result.valid){toast('보석 3개가 이어지는 자리로 옮겨 주세요');renderBoard();return;}busy=true;render();await playEvents(result.events);busy=false;render();}
function choose(i){if(busy||$('#dialog').open)return;const size=stageDesign(state.stage).size;if(selected<0){selected=i;renderBoard();return;}if(selected===i){selected=-1;renderBoard();return;}if(Math.abs(Math.floor(selected/size)-Math.floor(i/size))+Math.abs(selected%size-i%size)===1){const a=selected;swap(a,i);}else{selected=i;renderBoard();}}
function showIntro(){const d=stageDesign(state.stage);dialog(`<div class="dialog-kicker">THE NINE REALMS · ACT ${d.act+1}</div><h2 class="dialog-title">${d.title}</h2><p class="dialog-story">${esc(d.story)}<br><br>첫 매치는 마법을 충전합니다. <b>같은 색 두 번째 매치</b>부터 토템 마법이 몬스터를 공격합니다. 몬스터는 몇 번의 매치 뒤 반격합니다.</p><button id="introGo" class="primary">전투 시작 →</button>`,false);$('#introGo').onclick=()=>{audio.unlock();closeDialog();};}
function showVictory(e){const d=stageDesign(state.stage),unlock=e.unlock!=null?RUNES[e.unlock]:null;setMagePose('victory');setMonsterPose('groggy');$('#monsterSprite').classList.add('die');dialog(`<div class="dialog-kicker">VICTORY · STAGE ${state.stage}</div><h2 class="dialog-title">${state.stage===LAST_STAGE?'이세계의 수호자':esc(d.name)+' 격파'}</h2><p class="dialog-story">${state.stage===LAST_STAGE?'아즈라엘은 아홉 토템의 균형을 인정했습니다. 당신의 이야기는 이제 전설이 됩니다.':esc(d.story)}</p><div class="victory-gold">◈ +${e.reward} 코인</div>${unlock?`<div class="new-totem">✦ ${unlock.name}의 토템 획득 · ${unlock.spell} 해금</div>`:''}<button id="victoryNext" class="primary">${state.stage===LAST_STAGE?'여정의 기록 보기':'다음 전투 →'}</button><button id="victoryShop" class="secondary">장비와 스크롤 구매</button>`,false);$('#victoryNext').onclick=()=>{if(state.stage===LAST_STAGE){showJourney();return;}closeDialog();advanceStage(state);shuffleLeft=2;$('#monsterSprite').classList.remove('die');setMonsterPose('idle');setMagePose('idle');render();if(state.stage%10===1)showIntro();};$('#victoryShop').onclick=()=>showShop();}
function showDefeat(){setMagePose('groggy');dialog(`<div class="dialog-kicker">A SECOND CHANCE</div><h2 class="dialog-title">마법사는 다시 일어납니다</h2><p class="dialog-story">${esc(stageDesign(state.stage).enemy.name)}의 공격을 받았습니다. 보유한 코인과 장비는 유지됩니다. 상점에서 준비한 뒤 재도전하세요.</p><button id="retry" class="primary">이 전투 다시 도전</button><button id="defeatShop" class="secondary">상점 열기</button>`,false);$('#retry').onclick=()=>{closeDialog();state.battle=newBattle(state);shuffleLeft=2;setMagePose('idle');setMonsterPose('idle');render();};$('#defeatShop').onclick=()=>showShop();}
function showShop(tab=shopTab){shopTab=tab;const tabs=`<div class="shop-tabs"><button data-tab="gear" class="${tab==='gear'?'active':''}">장비</button><button data-tab="scroll" class="${tab==='scroll'?'active':''}">연계 스크롤</button><button data-tab="train" class="${tab==='train'?'active':''}">토템 성장</button></div>`;
let items='';if(tab==='gear')items=Object.keys(GEAR).map(slot=>{const n=state.gear[slot]+1,g=GEAR[slot][n],title={staff:'지팡이',robe:'로브',ring:'반지'}[slot];return `<div class="shop-item"><b>${title} · ${g?g.name:'최고 등급'}</b><p>${g?slot==='staff'?`마법 공격력 +${g.attack}`:slot==='robe'?`최대 생명력 +${g.hp} · 방어 +${g.armor}`:`마법 집중 +${Math.round(g.focus*100)}%`:'이미 최고 등급입니다'}</p><button data-buy-gear="${slot}" ${!g||state.coins<g.price?'disabled':''}>${g?`◈ ${g.price} 구매`:'완성'}</button></div>`;}).join('');
if(tab==='scroll')items=SCROLLS.map(s=>`<div class="shop-item"><b>${s.icon} ${s.name}</b><p>${s.desc}</p><button data-buy-scroll="${s.id}" ${state.scrolls.includes(s.id)||state.coins<s.price?'disabled':''}>${state.scrolls.includes(s.id)?'보유 중':`◈ ${s.price} 구매`}</button></div>`).join('');
if(tab==='train')items=RUNES.slice(6).map((r,j)=>{const i=j+6,l=state.levels[i],cost=55+l*65;return `<div class="shop-item"><b>${r.icon} ${r.name} 토템 · Lv.${l}</b><p>${l?`${r.spell} 위력 증가`:`${r.unlock-1}단계 문지기를 쓰러뜨리면 해금`}</p><button data-train="${i}" ${!l||l>=5||state.coins<cost?'disabled':''}>${!l?'잠김':l>=5?'최고 레벨':`◈ ${cost} 성장`}</button></div>`;}).join('');
dialog(`<div class="dialog-kicker">TRAVELER'S MARKET · ◈ ${state.coins}</div><h2 class="dialog-title">원소의 상점</h2><p class="dialog-story">전투에서 얻은 코인으로 장비와 연계 마법을 준비하세요.</p>${tabs}<div class="shop-grid">${items}</div><button id="shopClose" class="secondary">전투로 돌아가기</button>`,true);
document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>showShop(el.dataset.tab));document.querySelectorAll('[data-buy-gear]').forEach(el=>el.onclick=()=>{if(buyGear(state,el.dataset.buyGear)){audio.match();render();showShop();}});document.querySelectorAll('[data-buy-scroll]').forEach(el=>el.onclick=()=>{if(buyScroll(state,el.dataset.buyScroll)){audio.charge();render();showShop();}});document.querySelectorAll('[data-train]').forEach(el=>el.onclick=()=>{if(trainRune(state,+el.dataset.train)){audio.charge();render();showShop();}});$('#shopClose').onclick=()=>{closeDialog();if(state.battle.phase==='won')showVictory({reward:stageDesign(state.stage).reward,unlock:null});if(state.battle.phase==='lost')showDefeat();};}
function showJourney(){const entries=ACTS.map((a,i)=>{const from=FIRST_STAGE+i*10,to=from+9,done=state.cleared.includes(to);return `<div class="story-step"><b>${from}–${to}</b><span><strong>${a.title}</strong> · ${a.goal}<br>${a.intro}<br>${done?`✓ ${a.reward} 획득`:`결전: ${a.boss}`}</span></div>`;}).join('');dialog(`<div class="dialog-kicker">YOUR JOURNEY</div><h2 class="dialog-title">아홉 토템의 여정</h2><p class="dialog-story">현재 ${state.stage}단계 · ${state.cleared.length}번 승리 · 코인 ◈ ${state.coins}</p><div class="story-steps">${entries}</div><button id="journeyClose" class="secondary">돌아가기</button>`);$('#journeyClose').onclick=()=>{closeDialog();if(state.battle.phase==='won')showVictory({reward:stageDesign(state.stage).reward,unlock:null});};}
$('#board').addEventListener('click',e=>{const gem=e.target.closest('[data-i]');if(gem)choose(+gem.dataset.i);});let start=null;$('#board').addEventListener('pointerdown',e=>{const gem=e.target.closest('[data-i]');if(gem)start={i:+gem.dataset.i,x:e.clientX,y:e.clientY};});$('#board').addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.max(Math.abs(dx),Math.abs(dy))>20){const size=stageDesign(state.stage).size,j=Math.abs(dx)>Math.abs(dy)?start.i+(dx>0?1:-1):start.i+(dy>0?size:-size);const sameRow=Math.floor(start.i/size)===Math.floor(j/size);if(j>=0&&j<size*size&&(Math.abs(dx)<=Math.abs(dy)||sameRow)){e.preventDefault();e.stopPropagation();swap(start.i,j);}}start=null;});
$('#shopOpen').onclick=$('#shopOpenAside').onclick=()=>showShop();$('#journeyOpen').onclick=showJourney;$('#dialogClose').onclick=closeDialog;
$('#soundToggle').onclick=()=>{audio.setEnabled(!audio.enabled);if(audio.enabled)audio.unlock();renderStats();try{localStorage.setItem('solar-relic-audio-v3',JSON.stringify({enabled:audio.enabled,master:audio.master,effects:audio.effects,music:audio.music}));}catch{}};
$('#shuffleButton').onclick=()=>{if(busy||state.battle.phase!=='playing')return;if(shuffleLeft<=0){toast('이 전투의 섞기를 모두 사용했습니다');return;}const d=stageDesign(state.stage);state.battle.board=makeBoard(d.size,d.colors);shuffleLeft--;selected=-1;audio.charge();render();toast('보석을 다시 섞었습니다');};
document.addEventListener('pointerdown',()=>audio.unlock(),{once:true});setInterval(()=>audio.beat(),180);render();if(state.battle.phase==='playing'&&state.stage===FIRST_STAGE&&state.battle.turn===0)showIntro();else if(state.battle.phase==='won')showVictory({reward:stageDesign(state.stage).reward,unlock:null});else if(state.battle.phase==='lost')showDefeat();
